#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ld = long double;

#define all(a) a.begin(), a.end()
#define rall(a) a.rbegin(), a.rend()
#define rep(i, n) for(int i = 0; i < (n); i += 1)
#define len(a) ((int)(a).size())

const ll inf = 1e18;
mt19937 rnd(234);
#define int ll
inline void solve() {
    int n, k;
    cin >> n >> k;
    vector <int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    vector <int> pref(n + 1);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + a[i];

    map <int, int> suf_vals;
    map <int, int> pref_vals;

    for (int i = 1; i <= n; ++i) suf_vals[pref[i]]++;

    int answer = 0;

    for (int l = 0; l < n; ++l) {
        int pr = pref[l];
        int sum = pref.back();

        int suf_cnt = suf_vals[pr];
        int pref_cnt = pref_vals[pr - sum];

        if (suf_cnt + pref_cnt == k) ++answer;
        if (l + 1 == n) break;

        pref_vals[pref[l + 1]]++;
        suf_vals[pref[l + 1]]--;
    }

    cout << answer << "\n";
}

int32_t main() {
    if (1) {
        ios::sync_with_stdio(0);
        cin.tie(0);
        cout.tie(0);
    }
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
